import argparse
import json
import sys

from ethiobank_receipts import extract_receipt, get_receipt
from ethiobank_receipts.banks import BANKS
from ethiobank_receipts.errors import (
    BankUnavailable, InvalidReference, ReceiptNotFound, ReceiptParseError)


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Extract structured bank receipt data.\n"
            "Pass a transaction reference (not a URL) for any bank.\n"
            "CBE: pass the share link or token generated by the CBE app."
        )
    )
    parser.add_argument("bank", choices=sorted(BANKS), help="Bank name")
    parser.add_argument("reference", nargs="?",
                        help="Transaction reference, or a receipt URL on that bank's host")
    parser.add_argument("--ft", help="Retired: CBE no longer verifies by FT number")
    parser.add_argument("--account",
                        help="Retired: CBE no longer verifies by account number")
    parser.add_argument("--raw", action="store_true",
                        help="Print the bank's own field names instead of the normalized shape")
    parser.add_argument("--json", action="store_true", help="Print JSON")
    args = parser.parse_args()

    try:
        if args.bank == "cbe" and (args.ft or args.account):
            # FT+account verification was retired by CBE; the extractor raises a
            # message telling the caller to pass the share link/token instead.
            from ethiobank_receipts.extractors.cbe import extract_cbe_receipt_info_from_ft
            extract_cbe_receipt_info_from_ft(args.ft, args.account)
        if not args.reference:
            raise InvalidReference(
                "a reference is required (for CBE, the share link or token from the app)")
        result = (extract_receipt(args.bank, args.reference) if args.raw
                  else get_receipt(args.bank, args.reference))
    except InvalidReference as exc:
        sys.exit(f"Error: {exc}")
    except ReceiptNotFound as exc:
        sys.exit(f"Not found: {exc}")
    except BankUnavailable as exc:
        sys.exit(f"Bank unavailable: {exc}\n"
                 "The host may be unreachable from this network, or the reference "
                 "may be expired. Raise ETHIOBANK_READ_TIMEOUT to wait longer.")
    except ReceiptParseError as exc:
        sys.exit(f"Parse error: {exc}")

    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2))
    else:
        for key, value in result.items():
            if key == "raw":
                continue
            print(f"{key}: {value}")


if __name__ == "__main__":
    main()
